// The scenario "a_removed_object_s_handle_is_stale".
//
// Removing an object makes every handle to it stale: asking it anything fails
// with a stale-handle status rather than reaching whatever takes its slot next.
test "conformance: a_removed_object_s_handle_is_stale" {
    const cut = try otio.Document.init();
    defer cut.deinit();

    const track = try otio.Track.init(cut, "V1", "Video");
    const clip = try otio.Clip.init(cut, "doomed");
    try track.appendChild(clip.asNode());
    try cut.removeNode(clip.asNode());
    try std.testing.expectError(error.StaleHandle, clip.name(allocator));
    try expectName(track, "V1");
}

// The scenario "naming_an_object_from_another_timeline_is_refused".
//
// A call that only names an object refuses one from another timeline before
// asking the library, and the refusal leaves both timelines independent:
// releasing the one that refused leaves the other whole. Asserting only that
// the call failed would pass against a binding that merged the two timelines
// first and failed afterwards.
test "conformance: naming_an_object_from_another_timeline_is_refused" {
    var here: ?*otio.Document = try otio.Document.init();
    defer if (here) |doomed| doomed.deinit();
    const there = try otio.Document.init();
    defer there.deinit();

    const mine = try otio.Track.init(here.?, "V1", "Video");
    const ours = try otio.Clip.init(here.?, "Ours");
    try mine.appendChild(ours.asNode());
    const elsewhere = try otio.Track.init(there, "V2", "Video");
    const theirs = try otio.Clip.init(there, "Theirs");
    try elsewhere.appendChild(theirs.asNode());
    try std.testing.expectError(error.ForeignObject, mine.detachChild(theirs.asNode()));
    here.?.deinit();
    here = null;
    try std.testing.expectEqual(@as(usize, 1), try elsewhere.childCount());
    try expectName(theirs, "Theirs");
}

// The scenario "a_list_drawn_from_two_timelines_is_refused".
//
// A call handed a list refuses one whose objects come from two timelines,
// rather than merging them, and both timelines stay independent.
test "conformance: a_list_drawn_from_two_timelines_is_refused" {
    var here: ?*otio.Document = try otio.Document.init();
    defer if (here) |doomed| doomed.deinit();
    const there = try otio.Document.init();
    defer there.deinit();

    const first = try otio.Track.init(here.?, "V1", "Video");
    const second = try otio.Track.init(there, "V2", "Video");
    try std.testing.expectError(error.ForeignObject, here.?.flattenTracks(allocator, &.{ first.asNode(), second.asNode() }));
    here.?.deinit();
    here = null;
    try expectName(second, "V2");
}

/// The stack a timeline holds its tracks in, which a new one arrives with.
fn tracksOf(timeline: otio.Timeline) !otio.Stack {
    const held = (try timeline.tracks()) orelse {
        std.debug.print("the timeline holds no tracks\n", .{});
        return error.TestUnexpectedResult;
    };
    return held.asStack() orelse {
        std.debug.print("the tracks are held as a {}\n", .{try held.schemaKind()});
        return error.TestUnexpectedResult;
    };
}

